function recordSessionChanges(before,c){
const events=[],label=id=>get(id)?.name||id;
if(before.level!==c.level)events.push(`Уровень: ${before.level} → ${c.level}`);
for(const [k,v]of Object.entries(c.conditions))if(v!==before.conditions[k])events.push(`${R.CONDITIONS[k]?.[0]||k}: ${before.conditions[k]||0} → ${v||0}`);
for(const x of c.effects){const old=before.effects.find(y=>y.id===x.id);if(!old||old.active!==x.active)events.push(`${x.active?'Эффект включён':'Эффект выключен'}: ${x.name}`);}
for(const x of before.effects)if(!c.effects.some(y=>y.id===x.id))events.push(`Эффект удалён: ${x.name}`);
for(const x of c.inventory){const old=before.inventory.find(y=>y.uid===x.uid);if(!old)events.push(`Получено: ${label(x.id)} × ${x.quantity||1}`);else{if(old.quantity!==x.quantity)events.push(`Количество: ${label(x.id)} · ${old.quantity} → ${x.quantity}`);if(old.equipped!==x.equipped)events.push(`${x.equipped?'Экипировано':'Снято'}: ${label(x.id)}`);}}
for(const x of before.inventory)if(!c.inventory.some(y=>y.uid===x.uid))events.push(`Предмет убран: ${label(x.id)}`);
for(const id of c.feats)if(!before.feats.includes(id))events.push(`Получена способность: ${label(id)}`);
for(const id of before.feats)if(!c.feats.includes(id))events.push(`Способность убрана: ${label(id)}`);
for(const x of c.resources){const old=before.resources.find(y=>y.name===x.name);if(old&&old.value!==x.value)events.push(`${x.name}: ${old.value} → ${x.value}`);}
for(const x of c.journal){const old=before.journal.find(y=>y.id===x.id);if(x.done&&!old?.done)events.push(`Выполнено: ${x.title}`);else if(old?.done&&!x.done)events.push(`Возвращено в работу: ${x.title}`);}
if(before.panache!==c.panache)events.push(c.panache?'Кураж получен':'Кураж потрачен');
if(before.hero!==c.hero)events.push(`Очки героизма: ${before.hero} → ${c.hero}`);
for(const text of events)log(c,text);
}
function log(c,text,kind='routine'){if(!ListTableTools.sessionEvents([{text}]).length)return;c.log.unshift({text,time:Date.now()});c.log=c.log.slice(0,60);}
