 for(const k of [...info.skills,...info.skillChoices])if(target===cur()&&(clean.skills[k]||get(clean.classId)?.mechanics?.trainedSkills?.value?.includes(k))){body+=field(`${R.SKILLS[k][0]} уже изучен`, `<select data-background-replace="${k}">${option([['','Сохранить имеющееся обучение'],...Object.keys(R.SKILLS).filter(x=>!(clean.skills[x]>0)&&!chosenSkills.includes(x)&&!get(clean.classId)?.mechanics?.trainedSkills?.value?.includes(x)).map(x=>[x,R.SKILLS[x][0]])],old?.replacements?.[k]||'')}</select>`)+note('При совпадении можно выбрать другой необученный навык. Ступень мастерства сама не повышается.');}
