function applyBackgroundLore(c){const bg=get(c.background);if(!bg)return;R.applyBackground(c,bg,c.backgroundTraining?.id===bg.id?c.backgroundTraining.choices:{});}

const actionLabel=d=>d.actionType==='reaction'?'Реакция':d.actionType==='free'?'Свободное действие':d.actions?`${d.actions} ${d.actions===1?'действие':'действия'}`:'';
const traitPills=d=>(d.tags||[]).filter(tag=>window.TRAITS?.[tag]).map(tag=>`<button class="pill trait-pill" data-action="trait" data-tag="${esc(tag)}">${esc(window.TRAITS[tag].name.replace(/\bd(\d+)/g,'к$1'))}</button>`).join('');
const loreSubject=ListTableTools.loreSubject;
function row(d,action='detail',selected=false){return `<button class="item ${selected?'selected':''}" data-action="${action}" data-id="${esc(d.id)}"><span class="badge">${d.level||'•'}</span><span class="main"><b class="ability-title"><span class="ability-name">${esc(d.name)}</span>${ListAbilityDisplay.glyph(d)}</b><small>${esc([...d.traits.slice(0,3)].filter(Boolean).join(' · ')||cats[d.cat])}</small></span>${icon(selected?'check':'chevron')}</button>`;}
function header(){return `<header class="topbar"><button class="brand" data-action="characters" aria-label="Мои персонажи"><img src="brand.svg" alt=""><span class="brand-name"><b>Лист персонажа</b><small>Вторая редакция · Ремастер</small></span></button><div class="row">${ib(medieval?'key':'cloud','sync-settings','Синхронизация')}${ib('gear','settings','Настройки')}</div></header>`;}
let categoryScroll=0;const tabPositions={};
function render(){if($('.catalog-editions'))editionScroll=$('.catalog-editions').scrollLeft;if($('.tabs'))categoryScroll=$('.tabs').scrollLeft;if(wizard){try{localStorage.setItem('list-draft',JSON.stringify(wizard));}catch{}}const c=cur();if(localSearchOwner!==c?.id){bagQuery='';localSearchOwner=c?.id||'';}const scene=wizard?'wizard:'+wizard.step:'page:'+(c?.id||'none')+':'+tab+(tab==='catalog'?':'+category:tab==='abilities'?':'+abilityView:'');ListMotion.renderApp($('#app'),`<main class="shell">${header()}<div id="page-content" class="page-content" data-scene="${esc(scene)}">${storageError&&!storageWarningDismissed?`<div id="storage-warning">${note('Изменения пока не сохранены. Сделай экспорт.',true)}<button class="storage-warning-close" data-action="storage-warning-dismiss" aria-label="Закрыть предупреждение">${icon('close')}</button></div>`:''}${wizard?renderWizard():!c&&tab!=='catalog'?welcome():({sheet:()=>Upgrade.layout(sheet()),abilities:abilities,bag:bag,catalog:catalog}[tab]||sheet)()}</div></main>${wizard?'':`<nav class="nav" aria-label="Основные разделы"><div class="nav-inner"><span class="nav-active-surface" data-motion-key="nav-surface" aria-hidden="true"></span>${[['sheet','sheet','Лист'],['abilities','spark','Умения'],['bag','bag','Рюкзак'],['catalog','book','Справочник']].map(([id,ic,label])=>`<button data-action="tab" data-tab="${id}" class="${tab===id?'on':''}" ${tab===id?'aria-current="page"':''}>${icon(ic)}${label}</button>`).join('')}</div></nav>`}`,scene);if($('.tabs'))$('.tabs').scrollLeft=categoryScroll;if($('.catalog-editions'))$('.catalog-editions').scrollLeft=editionScroll;ListSearchHint.mount($('#catalog-search')||$('#bag-search'));}
function welcome(){return `<section class="intro">${medieval?'<span class="fantasy-welcome-mark" aria-hidden="true"></span>':'<img src="brand.svg" alt="">'}<div class="eyebrow">Всё готово, кроме персонажа</div><h1 class="edition-title" style="margin-top:14px">Pathfinder 2e<br><span class="pink">Remastered</span></h1><p>Работает и без сети</p>${btn(icon('plus')+'Создать персонажа','create','','primary full')}<button class="linkbtn" data-action="import" style="margin-top:20px">Импортировать персонажа</button></section>`;}
function sheet(){const c=cur();if(!c)return welcome();const a=R.calculate(c,db),cls=get(c.classId),weapons=c.inventory.filter(x=>x.equipped&&get(x.id)?.type==='weapon');return `<div class="hero"><div class="row between"><button class="hero-name" data-action="character-edit"><span class="avatar">${c.portrait?`<img src="${esc(c.portrait)}" alt="Фото персонажа">`:icon('camera')}</span><span><h1>${esc(c.name)}</h1><p class="subtitle">${esc([get(c.ancestry)?.name,cls?.name].filter(Boolean).join(' · '))}</p></span></button><button class="level" data-action="level" aria-label="Уровень ${c.level}. Повысить уровень"><b>${c.level}</b><small>уровень</small></button></div></div><div class="combat"><section><div class="health-layout"><div class="health"><div class="head row between"><span class="eyebrow">Здоровье</span>${icon('heart')}</div><div class="hp"><b>${c.hp??a.maxHp}</b><button class="hp-maximum" data-action="number-explain" data-key="hp" aria-label="Состав максимума очков здоровья">/ ${a.maxHp}</button></div><div class="meter" data-fill="${R.clamp((c.hp??a.maxHp)/a.maxHp,0,1)}" data-owner="${esc(c.id)}"><div style="transform:scaleX(${R.clamp((c.hp??a.maxHp)/a.maxHp,0,1)})"></div>${medieval?'<canvas class="vial-liquid" aria-hidden="true"></canvas>':''}</div><div class="row">${btn('− Урон','health','data-mode="damage"')}${btn('+ Лечение','health','data-mode="heal"','','')}</div>${c.tempHp?`<div class="small" style="margin-top:10px">+${c.tempHp} временных ОЗ</div>`:''}</div><div class="stats"><button class="stat" data-action="defense">${icon('shield')}<b>${a.ac}</b><small>Класс брони</small></button><button class="stat" data-action="check" data-label="Восприятие" data-bonus="${a.perception}">${icon('eye')}<b>${R.signed(a.perception)}</b><small>Восприятие</small></button><button class="stat" data-action="speed">${icon('foot')}<b>${a.speed}</b><small>Скорость · футы</small></button><button class="stat" data-action="skills">${icon('dice')}<b>${Object.values(a.skillRanks).filter(x=>x>0).length+(c.lores||[]).filter(x=>x.rank>0).length}</b><small>Обучено навыков</small></button></div></div><div class="saves">${[['fortitude','Стойкость'],['reflex','Рефлекс'],['will','Воля']].map(([k,n])=>`<button class="save" data-action="check" data-label="${n}" data-bonus="${a.saves[k]}"><b>${R.signed(a.saves[k])}</b><small>${n}</small></button>`).join('')}</div></section><section>${quickRows()?`<div class="section"><h2>Быстрый доступ</h2></div><div class="quick-grid" data-quick-group>${quickRows()}</div>`:''}<div class="section" style="margin-top:0"><h2>Атаки</h2><button class="linkbtn" data-action="new-turn">Новый ход</button></div><div class="stack">${weapons.length?weapons.map(w=>{const d=get(w.id),s=R.strike(c,w,db);return `<div class="weapon"><div class="row"><span class="weapon-icon">${icon('sword')}</span><div class="weapon-info"><b>${esc(d.name)}</b><small>${esc(d.traits.slice(0,3).join(' · ').replace(/\bd(\d+)/g,'к$1'))}</small></div><button class="attack" data-action="attack" data-uid="${w.uid}" aria-label="Атака: ${esc(d.name)}">${R.signed(s.bonus)}</button></div><div class="weapon-foot"><button class="linkbtn" data-action="weapon-damage" data-uid="${w.uid}">Урон ${s.damage}</button><span>${s.map?'Штраф −'+s.map:'Первая атака'}</span>${ib('book','detail','Описание оружия','data-id="'+d.id+'"')}</div></div>`;}).join(''):empty('Экипируй оружие в рюкзаке — атаки появятся здесь.')}${btn((medieval?'':icon('bag'))+'Снаряжение','tab','data-tab="bag"','ghost full')}</div><div class="section"><h2>Ресурсы</h2>${ib('plus','resource-new','Добавить ресурс')}</div><div class="stack"><div class="card resource"><div><b>Очки героизма</b><small>В начале сессии обычно 1</small></div><div class="pips">${[1,2,3].map(n=>`<button class="pip ${c.hero>=n?'on':''}" aria-label="Очки героизма: ${n}" data-action="hero" data-n="${n}">${medieval?'<span class="fantasy-art art-hero" aria-hidden="true"></span>':'✦'}</button>`).join('')}</div></div>${cls?.slug==='swashbuckler'?`<div class="card resource"><div><b>Кураж</b><small>${c.panache?'Есть. Время для финишера.':'Получи преимущество красиво.'}</small></div><button class="switch ${c.panache?'on':''}" role="switch" aria-checked="${c.panache}" aria-label="Кураж" data-action="panache"></button></div>`:''}${c.resources.map((r,i)=>`<div class="card resource"><button class="linkbtn" data-action="resource-edit" data-i="${i}">${esc(r.name)}</button><div class="counter">${btn('−','resource','data-i="'+i+'" data-delta="-1"','compact')}<b>${r.value}<small> / ${r.max}</small></b>${btn('+','resource','data-i="'+i+'" data-delta="1"','compact')}</div></div>`).join('')}</div><div class="section"><h2>Состояния</h2><div class="row status-tools">${Object.values(c.conditions).some(Boolean)||c.effects.some(e=>e.active&&e.rounds!==0)?`<button class="linkbtn" data-action="statuses-clear">Очистить всё</button>`:''}<button class="linkbtn" data-action="effects">Эффекты</button>${ib('plus','conditions','Изменить состояния')}</div></div><div class="chips conditions-chips">${Object.entries(c.conditions).filter(([,v])=>v).map(([k,v])=>`<button class="chip on" data-action="conditions">${R.CONDITIONS[k][0]}${R.CONDITIONS[k][2]?' '+v:''}</button>`).join('')||(!c.effects.some(e=>e.active&&e.rounds!==0)?'<span class="small">Нет активных состояний и эффектов</span>':'')}${c.effects.filter(e=>e.active&&e.rounds!==0).map(e=>`<button class="chip on status-chip" data-action="effects">${esc(e.name)}${e.rounds!==null?' · '+R.roundLabel(e.rounds):''}</button>`).join('')}</div><div class="section"><h2>За столом</h2></div><div class="grid two">${btn(icon('edit')+'Заметки','notebook')}${btn(icon('moon')+'Отдых','rest')}${btn((medieval?svgIcon('sheet'):icon('sheet'))+'Журнал','log')}${btn((medieval?svgIcon('dice'):icon('dice'))+'Броски','roll-history')}${c.spells.length?btn(icon('spark')+'Магия','magic'):''}</div></section></div><div class="saved">${storageError?'Не сохранено':cfg.url?'Сохранено на устройстве · синхронизация в настройках':'Сохранено на устройстве'}${c.demo?' · пример персонажа':''}</div>`;}
let abilityView='source';const abilityGroupClosed=new Set();
function abilityRows(){const c=cur(),ids=[...new Set([...c.feats,...R.features(c,db).map(d=>d.id)])],items=ListAbilityDisplay.presentationItems(ids.map(get).filter(Boolean)),groups=ListAbilityDisplay.groups(c,items,R,db,abilityView);return groups.map(g=>`<details class="ability-group" data-group="${g.key}" ${!abilityGroupClosed.has(abilityView+':'+g.key)?'open':''}><summary>${esc(g.label)}</summary><div class="ability-group-list">${g.items.map(d=>row(d).replace('</small>',(R.archetypeSource(c,d.id)?'<span class="archetype-source">'+esc(R.archetypeSource(c,d.id))+'</span>':'')+'</small>')).join('')}</div></details>`).join('')||empty('Способности можно добавить из справочника.');}
document.addEventListener('list-fold',e=>{const el=e.target;if(el.matches?.('.ability-group')){const key=abilityView+':'+el.dataset.group;if(e.detail.open)abilityGroupClosed.delete(key);else abilityGroupClosed.add(key);}});
document.addEventListener('toggle',e=>{const el=e.target;if(el.matches?.('.ability-group')){const key=abilityView+':'+el.dataset.group;if(el.closest('.motion-snapshot'))return;if(ListMotion.expanded(el))abilityGroupClosed.delete(key);else abilityGroupClosed.add(key);}},true);

function abilities(){const c=cur();if(!c)return welcome();const fs=R.features(c,db),ids=[...new Set([...c.feats,...fs.map(d=>d.id)])],a=R.calculate(c,db),choices=R.classChoiceSets(c,db),archetypeChoices=Archetypes.summary();return `<div class="title"><div><h1>Умения</h1><p class="subtitle">То, что делает героя твоим</p></div>${ib('plus','add-ability','Добавить способность')}</div><div class="section"><h2>Характеристики</h2><button class="linkbtn" data-action="attributes">Изменить</button></div><div class="attrs">${Object.entries(R.ATTRS).map(([k,n])=>`<div class="attr"><b>${R.signed(c.attributes[k])}</b><small>${n}</small></div>`).join('')}</div><div class="section"><h2>Языки и Лор</h2><button class="linkbtn" data-action="knowledge">Изменить</button></div><div class="card languages-lore" style="margin-bottom:14px"><p class="small"><b>Языки:</b> ${esc(c.languages?.join(', ')||'не указаны')}</p><p class="small" style="margin-top:8px"><b>Лор:</b> ${esc(c.lores?.map(x=>loreSubject(x.name)).join(', ')||'не указан')}</p><p class="small" style="margin-top:8px"><b>Предыстория:</b> ${c.background?`<button class="background-inline" data-action="detail" data-id="${esc(c.background)}">${esc(get(c.background)?.name||'Не найдена в справочнике')}</button>`:'не выбрана'}</p></div>${choices.length||archetypeChoices?`<div class="section"><h2>Выборы персонажа</h2>${ib(c.abilityCollapsed.choices?'chevron':'down','ability-collapse',c.abilityCollapsed.choices?'Развернуть блок':'Свернуть блок',`data-key="choices" aria-expanded="${!c.abilityCollapsed.choices}"`)}</div><div id="ability-choices" class="ability-block-body" ${c.abilityCollapsed.choices?'hidden':''}>${choices.map(x=>`<button class="item ${x.selected?'selected':''}" data-action="class-choice" data-flag="${esc(x.flag)}"><span class="badge">${x.selected?'✓':'?'}</span><span class="main"><b>${esc(x.sourceName)}</b><small>${x.selected?esc(x.choices.find(o=>o.id===x.selected)?.name||name(x.selected)):'Нужно выбрать вариант'}</small></span>${icon('chevron')}</button>`).join('')}${archetypeChoices}</div>`:''}<div class="section"><h2>Способности и особенности</h2>${ib(c.abilityCollapsed.features?'chevron':'down','ability-collapse',c.abilityCollapsed.features?'Развернуть блок':'Свернуть блок',`data-key="features" aria-expanded="${!c.abilityCollapsed.features}"`)}</div><div id="ability-features" class="ability-block-body" ${c.abilityCollapsed.features?'hidden':''}><div class="ability-view chips">${[['source','По источнику'],['usage','Действия и пассивные']].map(([k,n])=>btn(n,'ability-view',`data-view="${k}"`,'chip '+(abilityView===k?'on':''))).join('')}</div><div id="ability-results">${abilityRows()}</div></div>${V.magicSummary()}${note('Лист автоматически применяет поддерживаемые выборы класса и базовые повышения мастерства. Для редких сложных эффектов по-прежнему доступны ручные поправки.')}`;}
function bagRows(){const c=cur();return c.inventory.filter(x=>matches(get(x.id)||{name:'Неизвестный предмет'},bagQuery)).map(x=>{const d=get(x.id);return `<button class="item" data-action="inventory" data-uid="${x.uid}" data-equipped="${!!x.equipped}"><span class="weapon-icon">${icon(d?.type==='weapon'?'sword':d?.type==='armor'?'shield':'bag')}</span><span class="main"><b>${esc(d?.name||'Неизвестный предмет')}</b><small><span class="equipment-state">${x.equipped?'Экипировано':'В рюкзаке'}</span>${x.shoddy?' · &#1076;&#1088;&#1103;&#1085;&#1085;&#1086;&#1077;':''}${x.quantity>1?' · '+x.quantity+' шт.':''}</small></span>${icon('chevron')}</button>`;}).join('')||empty(bagQuery?'Предмет не найден. Попробуй другое название.':'Здесь пока пусто. Добавь стартовое снаряжение.');}
function wallet(c){return medieval?`<button class="card full fantasy-wallet" data-action="coins" aria-label="Монеты: ${c.coins.gp} золотых, ${c.coins.sp} серебряных, ${c.coins.cp} медных. Изменить количество"><span class="fantasy-wallet-title">Монеты</span><span class="fantasy-wallet-coins">${[['gp','gold','Золотые'],['sp','silver','Серебряные'],['cp','copper','Медные']].map(([key,metal,label])=>`<span class="fantasy-wallet-entry"><span class="fantasy-coin" style="--coin-digits:${String(c.coins[key]).length}"><span class="fantasy-art art-${metal}" aria-hidden="true"></span><b>${c.coins[key]}</b></span><small>${label}</small></span>`).join('')}</span></button>`:`<button class="card full row between" data-action="coins" style="margin-bottom:21px"><span class="small">Монеты</span><b>${c.coins.gp} зм · ${c.coins.sp} см · ${c.coins.cp} мм</b></button>`;}
function bag(){const c=cur();if(!c)return welcome();return `<div class="title"><div><h1>Рюкзак</h1><p class="subtitle">Оружие, снаряжение и находки</p></div>${ib('plus','add-item','Добавить предмет')}</div><div class="search bag-search">${icon('search')}<input id="bag-search" aria-label="Поиск в рюкзаке" placeholder="Найти предмет…" value="${esc(bagQuery)}"><button id="bag-clear" class="search-clear" data-action="bag-clear" aria-label="Очистить поиск в рюкзаке" ${bagQuery?'':'hidden'}>${icon('close')}</button></div>${wallet(c)}<div id="bag-results">${bagRows()}</div>`;}
function catalog(){const arr=CATALOG[category];return `<div class="title"><div><h1>Справочник</h1><p class="subtitle">Библиотека материалов и правил</p></div>${ib('book','about','Об источниках')}</div>${campaignVisible()?`<button class="card full row between campaign-link" data-action="campaign-guide" style="margin-bottom:16px"><span><b>Кампания · Авессалом</b><small>Агенты Граничной стражи · правила и справка</small></span>${icon('chevron')}</button>`:''}<div class="tabs">${Object.entries(cats).map(([k,n])=>`<button class="chip ${category===k?'on':''}" data-action="category" data-cat="${k}">${n}</button>`).join('')}</div><div class="catalog-search-row"><div class="search catalog-search">${icon('search')}<input id="catalog-search" placeholder="Найти способность…" aria-label="Поиск по справочнику" value="${esc(query)}" autocomplete="off"><button id="catalog-clear" class="search-clear" data-action="catalog-clear" aria-label="Очистить поиск" ${query?'':'hidden'}>${icon('close')}</button></div><button class="catalog-filter-button ${CatalogFilters.count()?'active':''}" data-action="catalog-filters-open" aria-label="Открыть фильтр справочника">${icon('filter')}<span>Фильтр${CatalogFilters.count()?' · '+CatalogFilters.count():''}</span></button></div>${CatalogFilters.toolbar()}<div id="catalog-recent" class="catalog-recent" hidden><h3>Недавно открывали</h3>${recentCatalog()}</div><div id="catalog-results">${arr?catalogResults():note('Открываем раздел…')}</div>`;}
function norm(s){return s.toLocaleLowerCase('ru').replaceAll('ё','е');}function matches(d,q){return ListComfortTools.matches(d,q);}
const campaignBackgroundInfo=d=>d?.cat==='backgrounds'?window.CAMPAIGN_EDGEWATCH?.backgrounds.find(x=>x.slug===d.slug):null;
function campaignBackgroundSummary(d){const x=campaignBackgroundInfo(d);return x?`<p class="subtitle">${esc(x.district)} · Граничная стража</p>${field('Повышения характеристик',note(esc(x.boosts)))}${field('Навыки',note(esc(x.skills)))}${field('Способность / снаряжение',note(esc(x.feat)))}${note(esc(x.bonus))}`:'';}
function catalogResults(){const arr=(CATALOG[category]||[]).filter(d=>CatalogFilters.filter(d)&&matches(d,query)&&(filter==='all'||(filter==='avessalom'?window.AVESSALOM_SOURCES?.ids.includes(d.id):d.remaster===(filter==='remaster')))).sort((a,b)=>a.name.localeCompare(b.name,'ru'));return `<div class="result-count">Найдено: ${arr.length.toLocaleString('ru')}</div>${filter==='avessalom'&&category==='backgrounds'&&arr.length?`<p class="small">${arr.filter(campaignBackgroundInfo).length} предысторий Граничной стражи · ${arr.filter(d=>!campaignBackgroundInfo(d)).length} из других материалов об Авессаломе</p><div class="section"><h2>Граничная стража</h2></div>${arr.filter(campaignBackgroundInfo).map(d=>row(d)).join('')}${arr.some(d=>!campaignBackgroundInfo(d))?`<div class="section"><h2>Другие материалы Авессалома</h2></div>${arr.filter(d=>!campaignBackgroundInfo(d)).map(d=>row(d)).join('')}`:''}`:arr.slice(0,limit).map(d=>row(d)).join('')||empty('Ничего не найдено.'+(query?' Поиск: «'+esc(query)+'».':'')+(CatalogFilters.count()?' Список ограничен выбранными фильтрами.':'')+' Измени запрос или условия.')+(CatalogFilters.count()?btn('Сбросить фильтры','catalog-filters-clear','','ghost full'):'')}${arr.length>limit?btn('Показать ещё','more','','ghost full'):''}`;}
function ruleHeader(d){return `<div class="chips">${ListAbilityDisplay.glyph(d)}<span class="pill pink">${window.AVESSALOM_SOURCES?.ids.includes(d.id)?'Авессалом':d.remaster?'Ремастер':'Раннее издание'}</span>${d.level?`<span class="pill">${d.cat==='spells'?'Ранг':'Уровень'} ${d.level}</span>`:''}${traitPills(d)||d.traits.map(t=>`<span class="pill">${esc(t.replace(/\bd(\d+)/g,'к$1'))}</span>`).join('')}</div>`;}window.renderRuleHeader=ruleHeader;
let pendingItem=null;
function itemAcquire(id,buy){const item=get(id),c=cur();if(!item||!c)return;pendingItem={id,buy,character:c.id};open(buy?'Купить предмет':'Получить предмет',`<p><b>${esc(item.name)}</b></p>${field('Количество',input('acquire-quantity',1,'number','min="1" max="9999"'))}<div id="acquire-summary" class="note"></div>`,btn(buy?'Купить':'Получить','item-acquire-confirm','','primary'),'item-acquire');updateAcquireSummary();}
function updateAcquireSummary(){if(!pendingItem||!$('#acquire-summary'))return;const button=$('[data-action="item-acquire-confirm"]'),quantity=Number($('#acquire-quantity').value);let message;try{if(!Number.isInteger(quantity)||quantity<1||quantity>9999)throw Error('Укажи количество от 1 до 9999.');if(pendingItem.buy){const q=R.purchaseQuote(cur(),get(pendingItem.id),quantity);message='Будет списано: '+R.coinLabel(q.total)+'. Остаток: '+R.coinLabel(q.balance)+'. При необходимости крупная монета будет разменяна.';}else message='Предмет будет добавлен в рюкзак. Монеты останутся без изменений.';button.disabled=false;}catch(e){message=e.message;button.disabled=true;}$('#acquire-summary').textContent=message;}
document.addEventListener('input',e=>{if(e.target.id==='acquire-quantity')updateAcquireSummary();});
async function detail(id){let d=get(id);if(!d)return toast('Запись не найдена.');CatalogMemory.visit(d);const c=cur(),known=c?.feats.includes(id)||c?.spells.includes(id),granted=c&&d.cat!=='spells'&&R.features({...c,feats:c.feats.filter(x=>x!==id)},db).some(x=>x.id===id),add=['feats','spells','equipment','class-features','ancestry-features'].includes(d.cat),availability=c?R.featAvailability(c,d,db):{ok:true,reason:''};open(d.name,`${ruleHeader(d)}${d.cat==='feats'&&!availability.ok?note(esc(availability.reason),true):''}${ruleMetadata(d,db,c)}${c?.resources.some(r=>ListTableTools.norm(r.name)===ListTableTools.norm(d.name))?c.resources.map((r,i)=>ListTableTools.norm(r.name)===ListTableTools.norm(d.name)?`<div class="card resource"><b>${esc(r.name)}</b><div class="counter">${btn('−','resource',`data-i="${i}" data-delta="-1"`,'compact')}<b>${r.value} / ${r.max}</b>${btn('+','resource',`data-i="${i}" data-delta="1"`,'compact')}</div></div>`:'').join(''):''}${campaignBackgroundSummary(d)}${pinButton(d)}<div class="rules-text">${window.renderRuleDescription(d.text||'Перевод описания пока отсутствует.',d.id)}</div><p class="small">Источник: ${esc(window.AVESSALOM_SOURCES?.byId?.[d.id]||d.source)} · ${d.license==='ORC'?'Открытая ролевая лицензия':'Открытая игровая лицензия'}</p>`,campaignBackgroundInfo(d)&&c?btn('Выбрать эту предысторию','campaign-background-select',`data-id="${esc(d.id)}"`,'primary'):granted?note('Уже есть в листе · получено автоматически.'):c&&Object.values(c.freeArchetype.choices).some(v=>v.id===id)?note(esc(R.archetypeSource(c,id)))+btn('Выборы архетипов','archetypes','','ghost'):c&&d.cat==='equipment'?btn('Получить','item-get',`data-id="${id}"`,'ghost')+btn('Купить','item-buy',`data-id="${id}"`,'primary'):c&&add&&(known||availability.ok||R.isArchetype(d))?btn(known?'Убрать из листа':d.cat==='equipment'?'В рюкзак':'Добавить в лист','learn',`data-id="${id}"`,known?'ghost':'primary'):'','detail');}
async function pick(cat,callback,{title=cats[cat],predicate=()=>true,selected=[],multi=false,classChoice=null,compare=(a,b)=>a.name.localeCompare(b.name,'ru')}={}){await load(cat);picker={cat,callback,predicate,selected,multi,compare};open(title,`${classChoice?`<div class="class-choice-tabs">${btn('Способность класса','advance-pick','data-kind="Способность класса" data-mode="class"',classChoice.mode==='class'?'compact primary':'compact ghost')}${btn('Архетип','advance-pick','data-kind="Способность класса" data-mode="dedication"',classChoice.mode==='dedication'?'compact primary':'compact ghost')}</div>`:''}<div class="search">${icon('search')}<input id="picker-search" placeholder="Название, сокращение или английское имя…" aria-label="Поиск вариантов"></div><div class="picker-list" id="picker-results"></div>`,multi?btn('Готово','picker-done','','primary'):'','picker');pickerResults('');}
function pickerResults(q){const arr=CATALOG[picker.cat].filter(d=>picker.predicate(d)&&matches(d,q)).sort(picker.compare);ListMotion.list($('#picker-results'),(arr.slice(0,100).map(d=>row(d,'pick',picker.selected.includes(d.id))).join('')||empty('Подходящих вариантов нет.'))+(arr.length>100?note('Первые 100 результатов. Уточни название.'):''));}
function fixedSkills(c){const bare=R.clone(c);bare.skills={};const auto=R.calculate(bare,db).skillRanks;return [...new Set([...(get(c.classId)?.mechanics?.trainedSkills?.value||[]),...(get(c.background)?.mechanics?.trainedSkills?.value||[]),...(c.backgroundTraining?.choices?.skill?[c.backgroundTraining.choices.skill]:[]),...Object.keys(auto).filter(k=>auto[k]>0)])].filter(k=>R.SKILLS[k]);}
function skillAllowance(c){const bare=R.clone(c);bare.skills={};bare.background='';const auto=R.calculate(bare,db).skillRanks,a=[...(get(c.classId)?.mechanics?.trainedSkills?.value||[]),...Object.keys(auto).filter(k=>auto[k]>0)],b=[...(get(c.background)?.mechanics?.trainedSkills?.value||[]),...(c.backgroundTraining?.choices?.skill?[c.backgroundTraining.choices.skill]:[])];return Math.max(0,(get(c.classId)?.mechanics?.trainedSkills?.additional||0)+c.attributes.int+b.filter(k=>a.includes(k)).length);}
function buildChoices(c,action){return R.classChoiceSets(c,db).map(x=>`<button class="item ${x.selected?'selected':''}" data-action="${action}" data-flag="${esc(x.flag)}"><span class="badge">${x.selected?'✓':'?'}</span><span class="main"><b>${esc(x.sourceName)}</b><small>${esc(x.choices.find(o=>o.id===x.selected)?.name||'Нужно выбрать')}</small></span>${icon('chevron')}</button>`).join('');}
function confirmBuildChoice(c,flag,id,isWizard){
 const set=R.classChoiceSets(c,db).find(x=>x.flag===flag),choice=set?.choices.find(x=>x.id===id);if(!choice)return toast('Этот вариант больше недоступен.');
 const next=R.clone(c);next.classChoices[flag]=id;const before=R.calculate(c,db),after=R.calculate(next,db),oldFeatures=R.features(c,db),newFeatures=R.features(next,db),added=newFeatures.filter(x=>!oldFeatures.some(y=>y.id===x.id)),removed=oldFeatures.filter(x=>!newFeatures.some(y=>y.id===x.id));
 const rows=[];for(const [key,label]of [['maxHp','Максимум ОЗ'],['ac','Класс брони'],['speed','Скорость'],['perception','Восприятие'],['spellDC','КС заклинаний'],['classDC','КС класса']])if(before[key]!==after[key])rows.push({label,before:before[key],after:after[key]});for(const [key,label]of Object.entries({fortitude:'Стойкость',reflex:'Рефлекс',will:'Воля'}))if(before.saves[key]!==after.saves[key])rows.push({label,before:before.saves[key],after:after.saves[key]});for(const [key,value]of Object.entries(before.skills))if(value!==after.skills[key])rows.push({label:R.SKILLS[key]?.[0]||key,before:value,after:after.skills[key]});
 const previous=set.choices.find(x=>x.id===set.selected)?.name||'Не выбран',source=get(set.sourceId),record=get(id),rules=record||source;
 choicePending={c,flag,id,isWizard,stamp:characterStamp(c)};
 let body=`<p class="subtitle">${esc(set.sourceName)}</p><div class="choice-summary"><span>${esc(previous)}</span><span aria-hidden="true">→</span><strong>${esc(choice.name)}</strong></div>`+note(set.selected?'Новый вариант заменит текущий. Лист пересчитает автоматически полученные умения и поправки. Изменения показаны ниже.':'Вариант будет сохранён для персонажа. Поддерживаемые способности и поправки применятся автоматически.');
 if(removed.length)body+=`<div class="section"><h3>Будет убрано из автоматических умений</h3></div><ul>${removed.map(x=>`<li>${esc(x.name)}</li>`).join('')}</ul>`;
 if(added.length)body+=`<div class="section"><h3>Будет получено</h3></div><ul>${added.map(x=>`<li>${esc(x.name)}</li>`).join('')}</ul>`;
 if(rows.length)body+=`<div class="section"><h3>Изменения показателей</h3></div><div class="equipment-diff">${rows.map(x=>`<div class="changed"><span>${esc(x.label)}</span><b>${x.before} → ${x.after}</b></div>`).join('')}</div>`;else body+=`<p class="small" style="margin-top:14px">Числовые показатели листа от этого выбора сейчас не изменятся.</p>`;
 if(rules?.text){const paragraph=rules.text.split(/\n\s*\n/)[0];body+=`<div class="section"><h3>Что даёт выбор</h3></div><div class="rules-text">${window.renderRuleDescription(paragraph,rules.id)}</div>${btn('Полное описание','detail',`data-id="${esc(rules.id)}"`,'ghost compact')}`;}
 body+=`<p class="small" style="margin-top:14px">Условные эффекты применяются по правилам описания. До подтверждения выбор не сохранён.</p>`;
 open(set.selected?'Изменить выбор?':'Подтвердить выбор?',body,btn('Вернуться','close','','ghost')+btn('Подтвердить','choice-confirm-apply','','primary'),'choice-confirm');
}
function applyBuildChoice(){const p=choicePending;if(!p||modal!=='choice-confirm')return;const c=p.isWizard?wizard?.c:cur();if(c!==p.c||characterStamp(c)!==p.stamp)return toast('Персонаж изменился. Открой выбор заново.');if(!R.classChoiceSets(c,db).find(x=>x.flag===p.flag)?.choices.some(x=>x.id===p.id))return toast('Этот вариант больше недоступен.');if(p.isWizard)c.classChoices[p.flag]=p.id;else change(cc=>{const before=R.calculate(cc,db).maxHp;cc.classChoices[p.flag]=p.id;const after=R.calculate(cc,db).maxHp;if(cc.hp!==null)cc.hp=R.clamp(cc.hp+after-before,0,after);});choicePending=null;close();render();toast('Выбор применён.');}
async function chooseBuildOption(c,flag,isWizard){const set=R.classChoiceSets(c,db).find(x=>x.flag===flag);if(!set)return toast('Этот выбор больше недоступен.');const apply=id=>confirmBuildChoice(c,flag,id,isWizard);const cat=get(set.choices[0]?.id)?.cat;if(cat&&set.choices.every(x=>get(x.id)?.cat===cat)){const allowed=new Set(set.choices.map(x=>x.id));await pick(cat,apply,{title:set.sourceName,predicate:x=>allowed.has(x.id)&&(x.cat!=='feats'||R.buildChoiceAvailability(c,flag,x,db).ok)&&!R.features(c,db).some(f=>f.id===x.id&&x.id!==set.selected)});}else{open(set.sourceName,note('Выбери вариант. Поддерживаемые эффекты применятся автоматически.')+'<div class="choice-options">'+set.choices.map(x=>btn('<span>'+esc(x.name)+'</span>',isWizard?'wizard-choice-set':'class-choice-set',`data-flag="${esc(flag)}" data-id="${esc(x.id)}"`,'full ghost choice-option')).join('')+'</div>','','class-choice');}}
function initBoosts(c){const key=get(c.classId)?.mechanics?.keyAbility?.value?.[0]||'str';c.key=key;const order=[key,'con','wis','dex','cha','int','str'].filter((v,i,a)=>a.indexOf(v)===i),allowed=get(c.background)?.mechanics?.boosts?.['0']?.value||Object.keys(R.ATTRS);c.boosts={ancestryMode:c.boosts.ancestryMode||'free',ancestry:order.slice(0,2),background:[order.find(k=>allowed.includes(k))||order[0]],free:order.slice(0,4)};c.boosts.background.push(order.find(k=>k!==c.boosts.background[0]));R.applyAncestryBoosts(c,db);}
function ancestryBoostFields(c){const plan=R.ancestryBoostPlan(c,db);return field('Характеристики от родословной',`<select id="wizard-ancestry-mode">${option([['standard','По родословной'],['free','Два свободных повышения']],c.boosts.ancestryMode||'free')}</select>`)+plan.slots.map((allowed,i)=>field(allowed.length===1?'Повышение · +1':'Выбери повышение · +1',`<select data-ancestry-slot="${i}" ${allowed.length===1?'disabled':''}>${allowed.map(k=>`<option value="${k}" ${c.boosts.ancestry[i]===k?'selected':''} ${c.boosts.ancestry.some((x,j)=>j!==i&&x===k)?'disabled':''}>${R.ATTRS[k]}</option>`).join('')}</select>`)).join('')+(plan.flaws.length?note('Недостаток родословной: '+plan.flaws.map(k=>R.ATTRS[k]+' −1').join(', '))+'' :note('Недостатков родословной нет.'));}
function renderWizard(){const c=wizard.c,step=wizard.step,titles=['Как зовут героя?','Откуда ты родом?','Сильные стороны','Чему ты научился?','Почти готово'];let body='';const selection=(label,key,cat)=>field(label,btn(`${esc(get(c[key])?.name||'Выбрать')} ${icon('chevron')}`,'wizard-pick',`data-key="${key}" data-cat="${cat}"`,'full ghost'));
if(step===0)body=field('Имя',input('wizard-name',c.name==='Новый герой'?'':c.name,'text','maxlength="100" placeholder="Имя персонажа"'))+selection('Класс','classId','classes')+(get(c.classId)?note(esc(get(c.classId).text.split('\n\n')[0])):'');
if(step===0&&c.classId)body+=buildChoices(c,'wizard-choice');
if(step===1)body=selection('Родословная','ancestry','ancestries')+selection('Наследие','heritage','heritages')+selection('Предыстория · необязательно','background','backgrounds')+(c.background?btn('Выбрать предысторию позже','wizard-background-clear','','ghost full'):note('Можно пропустить и выбрать предысторию в листе позже.'))+note('Редкость и доступ к необычным вариантам согласуй с ведущим. Совместимые материалы ранних изданий тоже доступны.');
if(step===2){const keys=get(c.classId)?.mechanics?.keyAbility?.value||Object.keys(R.ATTRS);body=field('Ключевая характеристика класса',`<select id="wizard-key">${option(keys.map(k=>[k,R.ATTRS[k]]),c.key)}</select>`)+ancestryBoostFields(c)+[...(c.background?[['background','Предыстория · два повышения',2]]:[]),['free','Четыре свободных повышения',4]].map(([k,t,n])=>`<div class="field"><label>${t} (${c.boosts[k].length}/${n})</label><div class="boosts">${Object.keys(R.ATTRS).map(a=>`<button class="chip ${c.boosts[k].includes(a)?'on':''}" data-action="boost" data-group="${k}" data-stat="${a}">${shortAttr(a)}</button>`).join('')}</div></div>`).join('')+`<div class="attrs">${Object.entries(c.attributes).map(([k,v])=>`<div class="attr"><b>${R.signed(v)}</b><small>${R.ATTRS[k]}</small></div>`).join('')}</div>`+note((!c.background?'Предыстория пока не выбрана: её повышения, навыки и способность ещё не начислены. ':'')+'Родословная: стандартные повышения и недостатки или два свободных повышения без недостатков. Предыстория: хотя бы одно повышение из указанных в её описании. Особые предыстории могут требовать ручной настройки.');}
if(step===3){const fixed=fixedSkills(c),selected=Object.keys(c.skills).filter(k=>!fixed.includes(k)&&c.skills[k]);body=`<p class="subtitle" style="margin-bottom:18px">Выбери ещё ${skillAllowance(c)} навыков. Выбрано: ${selected.length}.</p><div class="skills-grid">${Object.entries(R.SKILLS).map(([k,[n]])=>`<button class="item ${c.skills[k]||fixed.includes(k)?'selected':''}" data-action="wizard-skill" data-key="${k}" ${fixed.includes(k)?'disabled':''}><span class="main"><b>${n}</b><small>${fixed.includes(k)?'От класса или предыстории':R.ATTRS[R.SKILLS[k][1]]}</small></span>${c.skills[k]||fixed.includes(k)?icon('check'):icon('plus')}</button>`).join('')}</div>${note('Лор — отдельный навык со специализациями. После создания героя его можно добавить и менять прямо в окне «Навыки».')}`;}
if(step===4){const a=R.calculate(c,db);body=`<div class="card"><h2>${esc(c.name)}</h2><p class="subtitle">${esc([name(c.ancestry),name(c.classId)].join(' · '))} · 1 уровень</p><p class="subtitle">${esc(c.background?name(c.background):'Предыстория пока не выбрана')}</p><div class="grid three" style="margin-top:20px"><div><b>${a.maxHp}</b><small> ОЗ</small></div><div><b>${a.ac}</b><small> КБ без брони</small></div><div><b>${a.speed}</b><small> футов</small></div></div></div><div class="section"><h2>Начальные способности</h2></div>${R.initialFeatKinds(c,db).map(kind=>{const selected=c.levelProgress['1:'+kind];return `<button class="item ${selected?'selected':''}" data-action="wizard-initial-feat" data-kind="${esc(kind)}"><span class="badge">${selected?'✓':'?'}</span><span class="main"><b>${esc(kind)}</b><small>${esc(selected?name(selected):'Нужно выбрать')}</small></span>${icon('chevron')}</button>`;}).join('')}${buildChoices(c,'wizard-choice')}${note('Способности предыстории и поддерживаемые умения класса и наследия выдаются автоматически. Заклинания и снаряжение можно настроить в листе после создания.')}`;}
return `<section class="wizard"><div class="row between"><span class="eyebrow">Создание · ${step+1} из 5</span><button class="linkbtn" data-action="wizard-cancel">Закрыть</button></div><div class="steps">${titles.map((_,i)=>`<i class="${i<=step?'on':''}"></i>`).join('')}</div><h1>${titles[step]}</h1><p class="introtext">${['Начни с имени и класса. Остальное выберем по шагам.','Родословная, наследие и жизнь до приключений.','Нажми на характеристику, чтобы выбрать повышение.','Навыки от класса и предыстории уже отмечены.','Проверь основу и переходи к своему листу.'][step]}</p>${body}<div class="wizard-foot">${step?btn('Назад','wizard-prev','','ghost'):''}${btn(step===4?'Создать героя':'Далее','wizard-next','','primary')}</div></section>`;}
function wizardNext(){const c=wizard.c,s=wizard.step;if(s===0){if(!c.name.trim()||c.name==='Новый герой')return toast('Введи имя персонажа.');if(!c.classId)return toast('Выбери класс.');const unresolved=R.classChoiceSets(c,db).filter(x=>!x.selected);if(unresolved.length)return toast('Заверши выбор: '+unresolved[0].sourceName);}if(s===1){if(!c.ancestry||!c.heritage)return toast('Выбери родословную и наследие.');if(!c.background){c.boosts.background=[];c.attributes=R.boostStats(c.boosts,c.key);}else if(!R.backgroundBoostsValid(get(c.background),c.boosts.background))initBoosts(c);}if(s===2){if(!R.ancestryBoostsValid(c,db)||(c.background&&c.boosts.background.length!==2)||c.boosts.free.length!==4)return toast('Заполни все повышения характеристик.');const allowed=get(c.background)?.mechanics?.boosts?.['0']?.value;if(c.background&&!R.backgroundBoostsValid(get(c.background),c.boosts.background))return toast('Одно повышение должно подходить предыстории.');c.skills={};const fix=fixedSkills(c);c.backgroundTraining??={id:'',skills:{},choices:{}};c.backgroundTraining.skills={};(get(c.classId)?.mechanics?.trainedSkills?.value||[]).filter(k=>R.SKILLS[k]).forEach(k=>c.skills[k]=1);applyBackgroundLore(c);}if(s===3){const fixed=fixedSkills(c),n=Object.keys(c.skills).filter(k=>c.skills[k]&&!fixed.includes(k)).length;if(n!==skillAllowance(c))return toast(`Нужно выбрать ещё ${skillAllowance(c)-n} навыков.`);}if(s===4){const missing=R.creationMissing(c,db);if(missing.length)return toast('Нужно выбрать: '+missing[0]);applyCampaignBackgroundExtras(c);c.hp=R.calculate(c,db).maxHp;S.characters.push(c);S.active=c.id;wizard=null;localStorage.removeItem('list-draft');tab='sheet';save();render();window.scrollTo({top:0,left:0,behavior:'instant'});if(!storageError){ListFeedback.emit('level-up',{deferVisual:true});ListMotion.revealCharacter($('#page-content'));}toast('Герой готов. Добавь стартовое снаряжение.');return;}wizard.step++;render();window.scrollTo(0,0);}
function levelKey(level,kind){return `${level}:${kind}`;}
function development(){const c=cur();if(!c)return;const next=Math.min(20,c.level+1),plan=c.level<20?R.levelPlan(c,db,next,next)[0]:null;const picked=(kind)=>{const value=c.levelProgress?.[levelKey(next,kind)];if(!value)return '';if(['Способность класса','Способность родословной','Способность навыка','Общая способность'].includes(kind))return get(value)?.name||'Выбрано';if(kind==='Повышение навыка')return R.SKILLS[value]?.[0]||value;if(kind==='Четыре повышения характеристик')return value.split(',').map(k=>R.ATTRS[k]||k).join(', ');return value;};const tasks=plan?.picks||[];open('Развитие персонажа',`<div class="card"><b>Сейчас: ${c.level} уровень</b>${c.level<20?`<p class="subtitle">Следующий: ${next} уровень</p>`:'<p class="subtitle">Достигнут 20 уровень.</p>'}</div>${plan?`<div class="section"><h2>Что выбрать на ${next} уровне</h2></div><div class="stack">${tasks.map(kind=>{const done=picked(kind);return `<button class="item ${done?'selected':''}" data-action="level-pick" data-level="${next}" data-kind="${esc(kind)}"><span class="badge">${done?'✓':'?'}</span><span class="main"><b>${esc(kind)}</b><small>${esc(done||'Нужно выбрать')}</small></span>${icon('chevron')}</button>`;}).join('')||empty('На этом уровне нет обязательного выбора способности или навыка.')}</div>${plan.features.length?`<div class="section"><h2>Автоматически от класса</h2></div>${plan.features.map(f=>row(get(f.id))).join('')}`:''}`:''}${note('Повышай уровень по одному. Так LIST не даст незаметно перепрыгнуть обязательные выборы. Сложные условия отдельных способностей всё равно показываются для проверки.')}`,c.level<20?btn('Исправить уровень вручную','level-manual','','ghost')+btn(`Повысить до ${next}`,'level-save',`data-level="${next}"`,'primary'):btn('Исправить уровень вручную','level-manual','','ghost'),'level');}
function skillIncrease(level){const c=cur(),a=R.calculate(c,db),cap=level>=15?4:level>=7?3:2;open('Повышение навыка',`<p class="subtitle">Выбери навык. Максимальная ступень на этом уровне: ${R.RANKS[cap]}.</p><div class="stack">${Object.entries(R.SKILLS).map(([k,[n]])=>{const rank=a.skillRanks?.[k]||0;return `<button class="item" data-action="level-skill-set" data-level="${level}" data-skill="${k}" ${rank>=cap?'disabled':''}><span class="main"><b>${n}</b><small>${R.RANKS[rank]} → ${rank<cap?R.RANKS[rank+1]:'предел'}</small></span><span class="n">${R.signed(a.skills[k])}</span></button>`;}).join('')}</div>`,'','level-skill');}
function abilityBoosts(level){const c=cur();open('Четыре повышения характеристик',`<p class="subtitle">Выбери четыре разные характеристики.</p><div class="boosts">${Object.entries(R.ATTRS).map(([k,n])=>`<button class="chip ${levelBoostSelection.includes(k)?'on':''}" data-action="level-boost" data-level="${level}" data-stat="${k}">${n} ${R.signed(c.attributes[k])}${c.attributes[k]>=4&&c.boostProgress?.[k]?' · половина уже есть':''}</button>`).join('')}</div>${note('При модификаторе +4 или выше два повышения дают +1. LIST запоминает промежуточную половину автоматически.')}`,btn(`Применить (${levelBoostSelection.length}/4)`,'level-boost-apply',`data-level="${level}"`,'primary'),'level-boosts');}
function skillsModal(edit=false){const c=cur(),a=R.calculate(c,db),lore=(c.lores||[]).map((x,i)=>`<button class="item" data-action="check" data-label="Лор: ${esc(loreSubject(x.name))}" data-bonus="${a.loreBonuses?.[i]??c.attributes.int}"><span class="main"><b>${esc(loreSubject(x.name))}</b><small>${R.RANKS[x.rank]}${x.backgroundGrant?' · от предыстории':''}</small></span><span class="n">${R.signed(a.loreBonuses?.[i]??c.attributes.int)}</span></button>`).join('');open(edit?'Обучение навыкам':'Навыки',`<div class="stack">${Object.entries(R.SKILLS).map(([k,[n]])=>edit?field(n,`<select data-skill="${k}">${option(R.RANKS.map((n,i)=>[String(i),n]),String(c.skills[k]||0))}</select>`):`<button class="item" data-action="check" data-label="${n}" data-bonus="${a.skills[k]}"><span class="main"><b>${n}</b><small>${R.RANKS[a.skillRanks?.[k]??(c.skills[k]||0)]}${(a.skillRanks?.[k]||0)>(c.skills[k]||0)?' · от класса':''}</small></span><span class="n">${R.signed(a.skills[k])}</span></button>`).join('')}</div><div class="section"><h2>Лор</h2><button class="linkbtn" data-action="knowledge">${(c.lores||[]).length?'Изменить':'Добавить Лор'}</button></div>${edit?note('Специализации Лора редактируются отдельно кнопкой выше.'):lore||empty('Лор — отдельный навык. Добавь специализацию, например «Авессалом», «Закон» или «Преступный мир».')}`,edit?btn('Сохранить','skills-save','','primary'):btn('Изменить обучение','skills-edit','','ghost'),'skills');}
function knowledge(){const c=cur(),a=R.calculate(c,db);open('Языки и Лор',field('Языки через запятую',input('knowledge-languages',(c.languages||[]).join(', '),'text','maxlength="1000" placeholder="Например: Всеобщий, Осириани"'))+`<div class="section"><h2>Лор</h2>${ib('plus','lore-new','Добавить Лор')}</div><div class="stack">${(c.lores||[]).map((x,i)=>`<button class="item" data-action="lore-edit" data-i="${i}"><span class="main"><b>${esc(loreSubject(x.name))}</b><small>${R.RANKS[x.rank]}${x.backgroundGrant?' · от предыстории':''}</small></span><span class="n">${R.signed(a.loreBonuses?.[i]??c.attributes.int)}</span></button>`).join('')||empty('Добавь специализацию Лора, которой владеет персонаж.')}</div>`,btn('Сохранить языки','knowledge-save','','primary'),'knowledge');}
