function conditions(){const c=cur();open('Состояния',`<div class="stack conditions-list">${Object.entries(R.CONDITIONS).map(([k,[n,t,valued]])=>`<div class="card condition-card ${c.conditions[k]?'active':''}"><div class="condition-head"><b>${n}</b>${valued?`<div class="counter">${btn('−','condition',`data-key="${k}" data-delta="-1" aria-label="Уменьшить: ${n}" ${!c.conditions[k]?'disabled':''}`,'compact')}<b>${c.conditions[k]||0}</b>${btn('+','condition',`data-key="${k}" data-delta="1" aria-label="Увеличить: ${n}" ${c.conditions[k]>=99?'disabled':''}`,'compact')}</div>`:`<button class="switch ${c.conditions[k]?'on':''}" data-action="condition" data-key="${k}" role="switch" aria-checked="${!!c.conditions[k]}" aria-label="${n}"></button>`}</div><p class="small" style="margin:9px 0 0">${t}</p></div>`).join('')}</div>`,btn('Очистить всё','statuses-clear','','ghost full'),'conditions');}
function health(mode){open(mode==='heal'?'Восстановить здоровье':'Получить урон',field(mode==='heal'?'Сколько ОЗ восстановить?':'Сколько урона?',input('health-amount','','number','min="0" max="100000" inputmode="numeric" placeholder="0"'))+field('Временные ОЗ (заменить)',input('temporary-hp',cur().tempHp,'number','min="0" max="100000" inputmode="numeric"'))+note('Сопротивления, слабости, умирание и лечение после отдыха учитываются вручную.'),btn(mode==='heal'?'Восстановить':'Применить','health-save',`data-mode="${mode}"`,'primary'),'health');setTimeout(()=>$('#health-amount')?.focus(),50);}
