function oldCheck(label,bonus,uid){open(label,`<p class="subtitle">Бросок 1к20 ${R.signed(bonus)}</p>${field('КС, если известна',input('check-dc','','number','min="0" max="1000" inputmode="numeric" placeholder="Необязательно"'))}${uid?note('Штраф многократной атаки учтён. После броска следующая атака получит больший штраф.'):''}`,btn(icon('dice')+'Бросить','roll-check',`data-label="${esc(label)}" data-bonus="${bonus}" ${uid?'data-uid="'+uid+'"':''}`,'primary'),'check');}
