function inventory(uid){const x=cur().inventory.find(x=>x.uid===uid),d=get(x.id);open(d?.name||'Предмет',(x.shoddy?note(window.CAMPAIGN_EDGEWATCH?.backgrounds.find(b=>b.slug===x.campaignGrant)?.bonus||''):'')+field('Количество',input('item-quantity',x.quantity,'number','min="1" max="9999" inputmode="numeric"'))+`<label class="check-label"><span>Экипировано</span><input id="item-equipped" type="checkbox" ${x.equipped?'checked':''}></label>`+(['weapon','armor'].includes(d?.type)?`<div class="grid two" style="margin-top:16px">${field('Руна мощи',input('item-potency',Math.max(x.potency||0,d.mechanics?.runes?.potency||0),'number','min="0" max="4"'))}${d.type==='weapon'?field('Руна разящего',input('item-striking',Math.max(x.striking||0,d.mechanics?.runes?.striking||0),'number','min="0" max="3"')):''}</div>`:'')+(d?.type==='weapon'?`<div class="grid two">${field('Поправка атаки',input('item-attack',x.attackBonus||0,'number','min="-100" max="100"'))}${field('Поправка урона',input('item-damage',x.damageBonus||0,'number','min="-100" max="100"'))}</div>`:'')+`<section id="equipment-preview" class="equipment-preview" data-uid="${esc(uid)}" aria-live="polite"></section><button class="linkbtn" data-action="detail" data-id="${esc(x.id)}">Описание предмета</button>`,btn('Убрать','item-delete',`data-uid="${uid}"`,'ghost')+btn('Сохранить','item-save',`data-uid="${uid}"`,'primary'),'inventory');Upgrade.equipmentPreview(uid);}
function campaignGuide(){const g=window.CAMPAIGN_EDGEWATCH,c=cur(),active=!!c&&R.campaignId(c,db)===g.id,bg=g.backgrounds;open('Кампания · '+g.name,`<p class="subtitle">${esc(g.summary)}</p>${active?note('Правила кампании включены для текущего персонажа.'):''}<details class="progression"><summary>Особые правила кампании</summary>${g.specialRules.map(x=>`<div class="campaign-block"><b>${esc(x.title)}</b><p>${esc(x.text)}</p></div>`).join('')}</details><details class="progression"><summary>Создание персонажа</summary><div class="campaign-block"><b>Роль героя</b><p>${esc(g.creation.duty)}</p><b>Родословные</b><p>${esc(g.creation.ancestries)}</p><b>Классы</b><p>${esc(g.creation.classes)}</p><b>Языки</b><p>${esc(g.creation.languages.join(', '))}</p><p class="small">${esc(g.creation.languageNote)}</p><b>Религии</b><p>${esc(g.creation.religions)}</p><b>Полезный Лор</b><p>${esc(g.creation.lore.join(', '))}</p><p class="small">${esc(g.creation.loreNote)}</p></div></details><details class="progression"><summary>${bg.length} предысторий Граничной стражи</summary>${bg.map((x,i)=>`<button class="item" data-action="campaign-background" data-i="${i}"><span class="badge">${i+1}</span><span class="main"><b>${esc(x.name)}</b><small>${esc(x.district)} · ${esc(x.boosts)}</small></span>${icon('chevron')}</button>`).join('')}<div class="campaign-block"><b>Подходящие обычные предыстории</b><p>${esc(g.creation.recommendedCoreBackgrounds.join(', '))}</p></div></details><details class="progression"><summary>Авессалом и Сияющий фестиваль</summary><div class="campaign-block"><b>Сияющий фестиваль</b><p>${esc(g.festival)}</p><b>Граничная стража</b><p>${esc(g.edgewatch)}</p><b>Первый день службы</b><p>${esc(g.duty)}</p></div></details><details class="progression"><summary>Районы Авессалома</summary>${g.districts.map(x=>`<div class="campaign-block"><b>${esc(x.name)}</b><p>${esc(x.text)}</p></div>`).join('')}<div class="campaign-block"><b>Карта в руководстве</b><p>${esc(g.mapDistricts.join(' · '))}</p></div></details><details class="progression"><summary>Предупреждения о содержании</summary><div class="campaign-block"><p>${esc(g.warnings.join(' · '))}</p></div></details><p class="small" style="margin-top:18px">Источник кампанийного пакета: ${esc(g.source)}. Текст в приложении структурирован и пересказан для быстрого использования за столом.</p>`,c?btn(active?'Отключить правила кампании':'Использовать правила кампании','campaign-toggle','','primary'):'','campaign');}
function campaignBackground(i){const x=window.CAMPAIGN_EDGEWATCH.backgrounds[Number(i)],entry=CATALOG.backgrounds?.find(b=>b.slug===x?.slug);if(entry)detail(entry.id);else toast('Предыстория не найдена.');}
function itemFeedback(item,equipped=false,equipmentChanged=false){
const owner=cur()?.id,from=tab,detail={material:ListFeedback.equipmentMaterial(get(item?.id)),equipped,equipmentChanged,deferVisual:true};
const feedback=item&&!storageError?ListFeedback.emit('equipment',detail):null;
close(()=>{if(feedback?.sample&&cur()?.id===owner&&tab===from&&ListFeedback.prefs().visual){const anchor=[...document.querySelectorAll('[data-action="inventory"]')].find(el=>el.dataset.uid===item.uid)||$('.nav [data-tab="bag"]');ListFeedbackVisual.emit('equipment',{...detail,anchor});}});
}
function walletFeedback(before,after){
const owner=cur()?.id,from=tab,changed=['gp','sp','cp'].some(k=>before[k]!==after[k]);
const feedback=changed&&!storageError?ListFeedback.emit('coins',{deferVisual:true}):null;
close(()=>{if(feedback?.sample&&cur()?.id===owner&&tab===from&&ListFeedback.prefs().visual)ListFeedbackVisual.emit('coins',{anchor:$('[data-action="coins"]')||$('.nav [data-tab="bag"]')});});
}
function rollFeedback(degree,anchor,roll={}){degree=ListFeedback.classifyRoll({...roll,degree});const kind=degree==='Критический успех'?'critical-success':degree==='Критический провал'?'critical-failure':'roll';window.ListFeedback?.emit(kind,{...roll,degree,anchor});}
async function switchDesign(design){
 if(design===ListTheme.design())return;
 if(!['modern','fantasy'].includes(design))throw Error('Неизвестное оформление.');
 if(storageBroken)throw Error('Сначала восстанови сохранение из резервной копии.');
 const result=Store.save(S);
 if(!result.localSaved&&!result.nativeConfirmed)throw Error('Сначала сохрани персонажей или сделай экспорт.');
 if(wizard)localStorage.setItem('list-draft',JSON.stringify(wizard));
 try{sessionStorage.setItem('list-design-view',JSON.stringify({tab,category,abilityView,wizard:!!wizard,settings:true}));}catch{}
 ListTheme.setDesign(design);
 location.reload();
}
function settings(){const group=(title,body)=>`<section class="settings-group"><h3>${title}</h3><div class="settings-panel">${body}</div></section>`;open('Настройки',group('Внешний вид',ListTheme.designControl()+ListTheme.control()+btn('Блоки главного листа','sheet-layout','','full'))+group('Отклик действий',ListFeedback.settingsHTML())+group('Персонаж и правила',btn('Мои персонажи','characters','','full')+btn('Кампания','ui-campaign','','full')+Archetypes.settingsRow()+btn('Ручные поправки','overrides','','full'))+group('Сохранение и перенос',btn('Экспорт персонажа','export','','full')+btn('Резервная копия всех персонажей','export-all','','full')+btn('Импорт из файла','import','','full')+btn('Синхронизация устройств','sync-settings','','full')+btn('Точки восстановления','backup','','ghost full'))+group('О приложении',btn('Источники и возможности','about','','full')),'','settings');document.querySelectorAll('.settings-panel>.btn').forEach(el=>{el.classList.add('settings-link');el.insertAdjacentHTML('beforeend',icon('chevron'));});}
function characters(){open('Мои персонажи',S.characters.map(c=>`<button class="item ${cur()?.id===c.id?'selected':''}" data-action="activate" data-id="${c.id}"><span class="avatar">${c.portrait?`<img src="${esc(c.portrait)}" alt="Аватар ${esc(c.name)}">`:icon('sheet')}</span><span class="main"><b>${esc(c.name)}</b><small>${esc(get(c.classId)?.name||'Персонаж')} · ${c.level} уровень</small></span>${icon('chevron')}</button>`).join('')||empty('Создай первого героя.'),btn('Импорт','import','','ghost')+btn('Создать','create','','primary'),'characters');}
function syncSettings(){open('Синхронизация',note('Патфайндер 2: Лист персонажа работает без интернета: персонажи и справочник хранятся на устройстве. Для обмена между устройствами подключи один сервер с одним ключом. Сервер ещё не подключён.')+field('Адрес сервера',input('sync-url',cfg.url,'url','placeholder="https://…" autocapitalize="none" autocomplete="off"'))+field('Ключ доступа',input('sync-token',cfg.token,'password','autocomplete="off" minlength="24"'))+`<label class="check-label"><span>Синхронизировать автоматически</span><input id="sync-auto" type="checkbox" ${cfg.auto?'checked':''}></label><p class="small" style="margin-top:15px">При конфликте сохраняются обе версии. Ключ даёт доступ к персонажам: используй собственный сервер и не публикуй его.</p>`,btn('Сохранить','sync-config','','ghost')+btn('Синхронизировать','sync-now','','primary'),'sync');}
function readSync(){const url=$('#sync-url').value.trim().replace(/\/+$/,''),token=$('#sync-token').value.trim();if(url){const u=new URL(url);if(u.protocol!=='https:'&&!(['localhost','127.0.0.1'].includes(u.hostname)&&u.protocol==='http:'))throw Error('Нужен адрес HTTPS.');if(u.username||u.password||u.search||u.hash)throw Error('Укажи адрес без пароля и параметров.');if(token.length<24)throw Error('Ключ должен содержать минимум 24 символа.');}if(url!==cfg.url||token!==cfg.token){S.revision=0;S.synced={};}cfg={url,token,auto:$('#sync-auto').checked};localStorage.setItem('list-sync',JSON.stringify(cfg));save(false);}
async function timedFetch(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{return await fetch(url,{...options,signal:controller.signal});}finally{clearTimeout(timer);}}
async function sync(manual=true){if(syncBusy||!cfg.url)return;syncBusy=true;try{const endpoint=cfg.url+'/v1/characters',headers={Authorization:'Bearer '+cfg.token},r=await timedFetch(endpoint,{headers});if(!r.ok)throw Error(r.status===401?'Сервер не принял ключ.':'Сервер недоступен.');const remote=await r.json();if(!Array.isArray(remote.characters)||remote.characters.length>100||!Number.isInteger(remote.revision))throw Error('Неизвестный формат сервера.');const incoming=remote.characters.map(R.validateCharacter);let merged=[],conflicts=0;const base=S.synced||{},local=new Map(S.characters.map(c=>[c.id,c])),remoteMap=new Map(incoming.map(c=>[c.id,c]));for(const id of new Set([...local.keys(),...remoteMap.keys(),...Object.keys(base)])){const lc=local.get(id),rc=remoteMap.get(id),ls=JSON.stringify(lc),rs=JSON.stringify(rc),bs=base[id];if(ls===rs){if(lc)merged.push(R.clone(lc));}else if(ls===bs){if(rc)merged.push(rc);}else if(rs===bs){if(lc)merged.push(R.clone(lc));}else{if(lc)merged.push(R.clone(lc));if(rc){if(lc){rc.id=R.uid();rc.name=(rc.name+' · другая версия').slice(0,100);conflicts++;}merged.push(rc);}}}const before=JSON.stringify(S.characters);const out=await timedFetch(endpoint,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({revision:remote.revision,characters:merged})});if(!out.ok)throw Error(out.status===409?'На другом устройстве появились изменения. Повтори синхронизацию.':'Не удалось записать изменения.');const done=await out.json();if(!Number.isInteger(done.revision))throw Error('Неверный ответ сервера.');S.revision=done.revision;S.synced=Object.fromEntries(merged.map(c=>[c.id,JSON.stringify(c)]));if(before===JSON.stringify(S.characters)){S.characters=merged;S.dirty=false;}else S.dirty=true;save(false);render();if(manual||conflicts)toast(conflicts?'Сохранены обе версии конфликтующих листов.':'Персонажи синхронизированы.');}catch(e){if(manual)toast(/[А-Яа-яЁё]/.test(e.message)?e.message:'Нет связи. Данные сохранены на устройстве.');}finally{syncBusy=false;}}
async function sendFile(filename,text){if(window.NativeBridge?.exportFile){NativeBridge.exportFile(filename,text);return;}if(window.webkit?.messageHandlers?.exportFile){window.webkit.messageHandlers.exportFile.postMessage({name:filename,text});return;}const blob=new Blob([text],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);toast('Файл подготовлен.');}
async function exportCharacter(){const c=cur();if(!c)return toast('Сначала создай персонажа.');await sendFile(c.name.replace(/[^\p{L}\p{N} -]/gu,'').slice(0,60)+'.json',JSON.stringify({format:'seriy-list',version:2,character:c},null,2));}
async function exportAll(){await sendFile('PF2e-Character-Sheet-персонажи.json',JSON.stringify({format:'seriy-list-library',version:2,exportedAt:Date.now(),characters:S.characters},null,2));}
function importText(text){try{if(text.length>4000000)throw Error('Файл слишком большой.');const obj=JSON.parse(text);if(obj.format==='seriy-list-backup'&&obj.state){obj.characters=obj.state.characters;obj.format='seriy-list-library';}if(obj.format==='seriy-list-library'){if(!Array.isArray(obj.characters)||obj.characters.length>100)throw Error('Неверный список персонажей.');const incoming=obj.characters.map(R.validateCharacter);if(incoming.length+S.characters.length>100)throw Error('Лимит — 100 персонажей.');Store.snapshot(S,'До импорта');for(const c of incoming){if(S.characters.some(x=>x.id===c.id)){c.id=R.uid();c.name=(c.name+' · копия').slice(0,100);}S.characters.push(c);}S.active=incoming[0]?.id||S.active;save();close();tab='sheet';render();toast('Добавлено персонажей: '+incoming.length);return;}const c=R.validateCharacter(obj.character||obj);if(S.characters.some(x=>x.id===c.id)){c.id=R.uid();c.name=(c.name+' · копия').slice(0,100);}if(S.characters.length>=100)throw Error('Лимит — 100 персонажей.');S.characters.push(c);S.active=c.id;save();close();tab='sheet';render();toast('Персонаж импортирован.');}catch(e){toast('Импорт: '+(/[А-Яа-яЁё]/.test(e.message)?e.message:'неверный формат файла.'));}}
window.receiveNativeFile=importText;$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(f){if(f.size>4000000)toast('Файл слишком большой.');else importText(await f.text());}e.target.value='';});
function slots(){const c=cur();open('Ячейки заклинаний',note('Укажи максимум по своему классу. Израсходованные ячейки восстанавливаются кнопкой «Ежедневные приготовления».')+`<div class="stack">${Array.from({length:10},(_,i)=>i+1).map(n=>`<div class="row"><b style="min-width:65px">Ранг ${n}</b>${input('slot-'+n,c.slots[n]?.max||0,'number','min="0" max="20" aria-label="Максимум ячеек ранга '+n+'"')}<small style="min-width:75px">осталось ${c.slots[n]?.value||0}</small></div>`).join('')}</div>`,btn('Сохранить','slots-save','','primary'),'slots');}
function attributes(){open('Характеристики',note('Здесь указаны модификаторы. Изменения применяются к производным параметрам, включая максимум ОЗ.')+`<div class="grid two">${Object.entries(R.ATTRS).map(([k,n])=>field(n,input('attr-'+k,cur().attributes[k],'number','min="-5" max="10"'))).join('')}</div>`,btn('Сохранить','attributes-save','','primary'),'attributes');}
function overrides(){const c=cur();if(!c)return;const fields={hp:'Максимум ОЗ',ac:'Класс брони',speed:'Скорость',perception:'Восприятие',fortitude:'Стойкость',reflex:'Рефлекс',will:'Воля',spellDC:'КС заклинаний'},ranks={simple:'Простое оружие',martial:'Воинское оружие',advanced:'Продвинутое оружие',unarmed:'Безоружные атаки',unarmored:'Без доспеха',light:'Лёгкие доспехи',medium:'Средние доспехи',heavy:'Тяжёлые доспехи',spellcasting:'Заклинания',classDC:'КС класса'};open('Поправки к расчётам',note('Число прибавляется к результату. Используй для эффектов, которые лист не учитывает автоматически.')+`<div class="grid two">${Object.entries(fields).map(([k,n])=>field(n,input('override-'+k,c.overrides[k]||0,'number','min="-1000" max="1000"'))).join('')}</div><h3 style="margin:18px 0">Степени мастерства</h3>`+Object.entries(ranks).map(([k,n])=>field(n,`<select data-rank="${k}">${option([['','По классу'],...R.RANKS.map((n,i)=>[String(i),n])],c.overrides.ranks?.[k]===undefined?'':String(c.overrides.ranks[k]))}</select>`)).join(''),btn('Сохранить','overrides-save','','primary'),'overrides');}
const num=(id,min,max)=>{const field=$(id),v=Number(field?.value);if(!Number.isInteger(v)||v<min||v>max){const error=Error(`Введи целое число от ${min} до ${max}.`);error.field=field;throw error;}return v;};
