window.addEventListener('storage',event=>{
 if(event.key==='list-state'&&event.newValue){
  const latest=Store.load(S);if(!latest.available||latest.rejected.length)return;
  const previousActive=S.active,existing=new Map(S.characters.map(c=>[c.id,c]));
  latest.state.characters=latest.state.characters.map(c=>{const current=existing.get(c.id);if(!current)return c;Object.assign(current,c);return current;});
  S=latest.state;undoHistory.length=0;
  if(previousActive!==S.active)close();render();
 }else if(event.key==='list-sync'){
  try{cfg={url:'',token:'',auto:false,...JSON.parse(event.newValue||'{}')};}catch{}
 }else if(event.key==='list-feedback-v1'){
  try{ListFeedback.configure(JSON.parse(event.newValue||'{}'));}catch{}
 }
});
